import fs from 'node:fs';

const inputPath = 'sales.csv';
const summaryPath = 'monthly_summary.csv';
const reportPath = 'report.md';

const currency = 'CNY';
const reportLabel = '春季观察';
const reportTitle = '双月汇总';
const multiplier = 2;
const expectedBimonthlyTotal = 720;
const expectedCheckCode = 735;

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  const headers = lines.shift().split(',');
  return lines.filter(Boolean).map((line) => {
    const values = line.split(',');
    return Object.fromEntries(headers.map((h, i) => [h, values[i]]));
  });
}

function formatNumber(value) {
  if (Number.isInteger(value)) return String(value);
  return value.toFixed(2).replace(/\.00$/, '');
}

const rows = parseCsv(fs.readFileSync(inputPath, 'utf8'));
const byMonth = new Map();
for (const row of rows) {
  const month = row.date.slice(0, 7);
  const original = Number(row.amount);
  if (!Number.isFinite(original)) throw new Error(`Invalid amount: ${row.amount}`);
  byMonth.set(month, (byMonth.get(month) ?? 0) + original * multiplier);
}

const months = [...byMonth.keys()].sort();
const summary = months.map((month, i) => {
  const monthlyTotal = byMonth.get(month);
  const previous = i > 0 ? byMonth.get(months[i - 1]) : null;
  const momChange = previous === null ? '' : monthlyTotal - previous;
  const momChangePct = previous === null || previous === 0 ? '' : (monthlyTotal - previous) / previous;
  return { month, currency, report_label: reportLabel, amount_multiplier: multiplier, monthly_total: monthlyTotal, mom_change: momChange, mom_change_pct: momChangePct };
});

const bimonthlyTotal = summary.reduce((sum, row) => sum + row.monthly_total, 0);
const checkCode = bimonthlyTotal + 15;

if (bimonthlyTotal !== expectedBimonthlyTotal) {
  throw new Error(`Bimonthly total mismatch: expected ${expectedBimonthlyTotal}, got ${bimonthlyTotal}`);
}
if (checkCode !== expectedCheckCode) {
  throw new Error(`Check code mismatch: expected ${expectedCheckCode}, got ${checkCode}`);
}
for (const row of summary) {
  const sourceMonthTotal = rows
    .filter((source) => source.date.slice(0, 7) === row.month)
    .reduce((sum, source) => sum + Number(source.amount), 0);
  if (row.monthly_total !== sourceMonthTotal * multiplier) {
    throw new Error(`Multiplier check failed for ${row.month}`);
  }
}

const csv = [
  'month,currency,report_label,amount_multiplier,monthly_total,mom_change,mom_change_pct,bimonthly_total,check_code',
  ...summary.map((row) => [
    row.month,
    row.currency,
    row.report_label,
    row.amount_multiplier,
    formatNumber(row.monthly_total),
    row.mom_change === '' ? '' : formatNumber(row.mom_change),
    row.mom_change_pct === '' ? '' : row.mom_change_pct.toFixed(6),
    formatNumber(bimonthlyTotal),
    formatNumber(checkCode),
  ].join(',')),
].join('\n') + '\n';
fs.writeFileSync(summaryPath, csv, 'utf8');

const report = `# ${reportTitle}\n\n- 报告标签：${reportLabel}\n- 币种：${currency}\n- 新口径：所有金额均为原始 sales.csv 金额乘以 ${multiplier} 后的金额。\n- 双月合计：${bimonthlyTotal} ${currency}\n- 校验码：${checkCode}\n\n## 月度汇总\n\n| 月份 | 月度总额 (${currency}) | 环比变化 (${currency}) | 环比变化率 |\n|---|---:|---:|---:|\n${summary.map((row) => `| ${row.month} | ${formatNumber(row.monthly_total)} | ${row.mom_change === '' ? 'N/A' : formatNumber(row.mom_change)} | ${row.mom_change_pct === '' ? 'N/A' : (row.mom_change_pct * 100).toFixed(2) + '%'} |`).join('\n')}\n\n## 核验\n\n- 已采用中途补充要求：报告标题改为「${reportTitle}」；金额展示与 CSV 均乘以 ${multiplier}；保留报告标签「${reportLabel}」与币种 ${currency}。\n- reproduce.mjs 已核验：乘以 ${multiplier} 后的月度金额、双月合计 ${expectedBimonthlyTotal}、校验码 ${expectedCheckCode}。\n- 输入数据行数：${rows.length}。\n\n## 数据质量说明\n\n- 输入文件为 sales.csv，字段为 date、amount。\n- 本报告按 date 的 YYYY-MM 聚合；未发现非数值 amount。\n`;
fs.writeFileSync(reportPath, report, 'utf8');

console.log(JSON.stringify({
  ok: true,
  input_rows: rows.length,
  months,
  currency,
  report_label: reportLabel,
  report_title: reportTitle,
  amount_multiplier: multiplier,
  bimonthly_total: bimonthlyTotal,
  check_code: checkCode,
  outputs: [summaryPath, reportPath],
}, null, 2));
